"""Daily PSP settlement reconciliation engine.

Standard library only, Python 3.10+.
"""

from __future__ import annotations

import re
from collections import defaultdict
from datetime import date, datetime, time, timedelta, timezone
from decimal import Decimal, localcontext
from zoneinfo import ZoneInfo

_NY = ZoneInfo("America/New_York")
_CUTOFF = time(17, 0)

_CHARGEBACK = "CHARGEBACK"
_CHARGEBACK_REVERSAL = "CHARGEBACK_REVERSAL"
_FEE = "FEE"

# ISO 4217 minor-unit exponents that differ from the default of 2.
_ZERO_DECIMAL = {
    "BIF", "CLP", "DJF", "GNF", "ISK", "JPY", "KMF", "KRW", "PYG",
    "RWF", "UGX", "UYI", "VND", "VUV", "XAF", "XOF", "XPF",
}
_THREE_DECIMAL = {"BHD", "IQD", "JOD", "KWD", "LYD", "OMR", "TND"}
_FOUR_DECIMAL = {"CLF", "UYW"}

_NUMBER_RE = re.compile(r"^(?:\d+(?:\.\d*)?|\.\d+)$")


def _precision(currency: str) -> int:
    cur = currency.upper()
    if cur in _ZERO_DECIMAL:
        return 0
    if cur in _THREE_DECIMAL:
        return 3
    if cur in _FOUR_DECIMAL:
        return 4
    return 2


def _parse_amount(text: str, currency: str) -> int:
    """Convert a processor major-unit string to exact integer minor units."""
    s = str(text).strip()
    negative = False
    if s.startswith("(") and s.endswith(")"):
        negative = True
        s = s[1:-1].strip()
    if s.startswith("-"):
        negative = not negative
        s = s[1:].strip()
    elif s.startswith("+"):
        s = s[1:].strip()
    s = s.replace(",", "")
    if not _NUMBER_RE.match(s):
        raise ValueError(f"Unparseable amount: {text!r}")

    prec = _precision(currency)
    with localcontext() as ctx:
        ctx.prec = 100
        minor = Decimal(s).scaleb(prec)
        if minor != minor.to_integral_value():
            raise ValueError(
                f"Amount {text!r} has more than {prec} decimal places for {currency}"
            )
        value = int(minor)
    return -value if negative else value


def _parse_event_time(text: str) -> datetime:
    s = str(text).strip()
    if s.endswith(("Z", "z")):
        s = s[:-1] + "+00:00"
    dt = datetime.fromisoformat(s)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)
    return dt


def _business_date(event_time: str, holidays: set[date]) -> str:
    local = _parse_event_time(event_time).astimezone(_NY)
    d = local.date()
    if local.time() >= _CUTOFF:
        d += timedelta(days=1)
    while d.weekday() >= 5 or d in holidays:
        d += timedelta(days=1)
    return d.isoformat()


def _add(groups: dict, key: tuple, amount: int, bdate: str) -> None:
    entry = groups.get(key)
    if entry is None:
        groups[key] = [amount, bdate]
    else:
        entry[0] += amount
        if bdate > entry[1]:  # ISO dates compare chronologically
            entry[1] = bdate


def reconcile(
    ledger_rows: list[dict],
    settlement_lines: list[dict],
    holidays: list[str],
) -> list[dict]:
    holiday_set = {date.fromisoformat(h.strip()) for h in holidays}

    # ---- Settlement side: keep only the highest file_seq per batch ----
    max_seq: dict[str, int] = {}
    for line in settlement_lines:
        batch = line["batch_id"]
        seq = int(str(line["file_seq"]).strip())
        if batch not in max_seq or seq > max_seq[batch]:
            max_seq[batch] = seq

    settle: dict[tuple, list] = {}
    for line in settlement_lines:
        if int(str(line["file_seq"]).strip()) != max_seq[line["batch_id"]]:
            continue
        ltype = line["line_type"].strip()
        if ltype == _FEE:
            continue
        currency = line["currency"].strip()
        key = (line["psp_ref"], ltype, currency)
        amount = _parse_amount(line["amount"], currency)
        bdate = _business_date(line["event_time"], holiday_set)
        _add(settle, key, amount, bdate)

    # ---- Ledger side ----
    ledger: dict[tuple, list] = {}
    for row in ledger_rows:
        if row["type"] == _FEE:
            continue
        key = (row["psp_ref"], row["type"], row["currency"])
        _add(ledger, key, int(row["amount_minor"]), row["business_date"])

    # ---- Chargeback netting ----
    pairs = {
        (ref, cur)
        for (ref, typ, cur) in settle
        if typ in (_CHARGEBACK, _CHARGEBACK_REVERSAL)
    }
    for ref, cur in pairs:
        cb = (ref, _CHARGEBACK, cur)
        rev = (ref, _CHARGEBACK_REVERSAL, cur)
        if cb in settle and rev in settle:
            if cb in ledger or rev in ledger:
                continue
            if settle[cb][0] + settle[rev][0] == 0:
                del settle[cb]
                del settle[rev]

    # ---- Matching ----
    results = []
    for key in set(settle) | set(ledger):
        ref, typ, cur = key
        s = settle.get(key)
        l = ledger.get(key)
        if s is not None and l is None:
            brk, delta = "MISSING_IN_LEDGER", s[0]
        elif l is not None and s is None:
            brk, delta = "MISSING_IN_SETTLEMENT", -l[0]
        elif s[0] != l[0]:
            brk, delta = "AMOUNT_MISMATCH", s[0] - l[0]
        elif s[1] != l[1]:
            brk, delta = "TIMING", 0
        else:
            continue
        results.append(
            {
                "psp_ref": ref,
                "type": typ,
                "currency": cur,
                "break": brk,
                "delta_minor": delta,
            }
        )

    results.sort(key=lambda r: (r["psp_ref"], r["type"], r["currency"]))
    return results
